INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2023/09/22 14:59:59", 2, -470.0, 2002, 1.47, "クローチェ", 1, 0.0, 1, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", "2023/06/30 12:00:00", 126401, 10001);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2023/09/22 14:59:59", 1, -470.0, 2002, 2.15, "クローチェ", 2, 0.0, 1, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", "2023/06/30 12:00:00", 126401, 10002);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2023/09/22 14:59:59", 2, -470.0, 2002, 0.0, "ライラエル", 2, 0.0, 1, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", "2023/06/30 12:00:00", 126501, 10003);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2023/09/22 14:59:59", 1, -470.0, 2002, 0.0, "ライラエル", 1, 0.0, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", "2023/06/30 12:00:00", 126501, 10004);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2023/12/22 14:59:59", 2, -470.0, 2002, 0.0, "リンド", 2, 0.0, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", "2023/09/15 15:00:00", 127702, 10005);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2023/12/22 14:59:59", 2, -470.0, 2002, 0.0, "リンド", 2, 0.0, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", "2023/09/15 15:00:00", 127702, 10006);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2023/12/22 14:59:59", 1, -470.0, 2002, 0.0, "ヴルム", 1, 0.0, 2, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", "2023/09/15 15:00:00", 127802, 10007);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2023/12/22 14:59:59", 1, -470.0, 2002, 6.5, "ヴルム", 2, 0.0, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", "2023/09/15 15:00:00", 127802, 10008);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/03/22 14:59:59", 1, -470.0, 2002, 0.0, "アネモネ", 2, 0.0, 3, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", "2023/12/15 15:00:00", 129602, 10009);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/03/22 14:59:59", 1, -470.0, 2002, 0.0, "アネモネ", 2, 0.0, 3, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", "2023/12/15 15:00:00", 129602, 10010);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/03/22 14:59:59", 1, -470.0, 2002, 0.0, "ネフィ=ネラ", 1, 0.0, 3, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", "2023/12/15 15:00:00", 129701, 10011);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/03/22 14:59:59", 1, -470.0, 2002, 6.2, "ネフィ=ネラ", 2, 0.0, 3, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", "2023/12/15 15:00:00", 129701, 10012);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/06/22 14:59:59", 5, -470.0, 2002, 3.1, "カノン", 3, 0.0, 4, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", "2024/03/15 15:00:00", 130301, 10013);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/06/22 14:59:59", 2, -470.0, 2002, 6.15, "カノン", 3, 0.0, 4, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", "2024/03/15 15:00:00", 130301, 10014);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/06/22 14:59:59", 2, -470.0, 2002, 0.0, "ナーナ", 2, 0.0, 4, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", "2024/03/15 15:00:00", 130401, 10015);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/06/22 14:59:59", 1, -470.0, 2002, 3.35, "ナーナ", 2, 0.0, 4, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", "2024/03/15 15:00:00", 130401, 10016);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/09/22 14:59:59", 1, -470.0, 2002, 0.0, "ホウオウ", 1, 0.0, 5, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", "2024/06/15 15:00:00", 130502, 10017);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/09/22 14:59:59", 1, -470.0, 2002, 3.18, "ホウオウ", 2, 0.0, 5, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", "2024/06/15 15:00:00", 130502, 10018);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (3, "2024/09/22 14:59:59", 4, -470.0, 2002, 0.0, "ホウオウ", 4, 0.0, 5, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", "2024/06/15 15:00:00", 130503, 10019);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/09/22 14:59:59", 2, -470.0, 2002, 4.9, "ネア", 1, 0.0, 5, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", "2024/06/15 15:00:00", 123301, 10020);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/09/22 14:59:59", 2, -470.0, 2002, 4.8, "ネア", 1, 0.0, 5, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", "2024/06/15 15:00:00", 123301, 10021);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/12/22 14:59:59", 1, -470.0, 2002, 4.922, "カリザ", 3, 0.0, 6, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", "2024/09/15 15:00:00", 133301, 10022);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/12/22 14:59:59", 5, -470.0, 2002, 9.638, "カリザ", 3, 0.0, 6, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", "2024/09/15 15:00:00", 133301, 10023);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2024/12/22 14:59:59", 2, -470.0, 2002, 2.88, "ミーア", 1, 0.0, 6, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", "2024/09/15 15:00:00", 133401, 10024);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2024/12/22 14:59:59", 1, -470.0, 2002, 4.818, "ミーア", 5, 0.0, 6, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", "2024/09/15 15:00:00", 133401, 10025);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/03/22 14:59:59", 1, -470.0, 2002, 1.78, "グレイス", 2, 0.0, 7, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", "2024/12/15 15:00:00", 133002, 10026);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/03/22 14:59:59", 7, -470.0, 2002, 6.15, "グレイス", 1, 0.0, 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", "2024/12/15 15:00:00", 133002, 10027);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/03/22 14:59:59", 2, -470.0, 2002, 4.28, "ヴァイオレット", 6, 0.0, 7, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", "2024/12/15 15:00:00", 133102, 10028);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/03/22 14:59:59", 1, -470.0, 2002, 0.0, "ヴァイオレット", 1, 0.0, 7, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", "2024/12/15 15:00:00", 133102, 10029);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/06/23 14:59:59", 1, -470.0, 2002, 5.53, "ルルィ", 2, 0.0, 8, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", "2025/03/15 15:00:00", 136902, 10030);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/06/23 14:59:59", 7, -470.0, 2002, 6.05, "ルルィ", 9, 0.0, 8, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", "2025/03/15 15:00:00", 136902, 10031);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/06/23 14:59:59", 1, -470.0, 2002, 0.0, "デュラン", 2, 0.0, 8, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", "2025/03/15 15:00:00", 137001, 10032);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/06/23 14:59:59", 1, -470.0, 2002, 0.0, "デュラン", 2, 0.0, 8, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", "2025/03/15 15:00:00", 137001, 10033);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/09/23 14:59:59", 2, -470.0, 2002, 0.0, "サツキ", 2, 0.0, 9, "おう\n好きなもん持ってきな", "2025/06/16 15:00:00", 135902, 10034);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/09/23 14:59:59", 6, -470.0, 2002, 4.935, "サツキ", 1, 0.0, 9, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", "2025/06/16 15:00:00", 135902, 10035);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/09/23 14:59:59", 5, -470.0, 2002, 7.441, "ユキノ", 2, 0.0, 9, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", "2025/06/16 15:00:00", 135802, 10036);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/09/23 14:59:59", 7, -470.0, 2002, 0.0, "ユキノ", 7, 0.0, 9, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", "2025/06/16 15:00:00", 135802, 10037);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/12/22 14:59:59", 2, -470.0, 2002, 2.295, "クルル", 2, 0.0, 10, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", "2025/09/16 15:00:00", 130901, 10038);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/12/22 14:59:59", 6, -470.0, 2002, 6.281, "クルル", 1, 0.0, 10, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", "2025/09/16 15:00:00", 130901, 10039);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2025/12/22 14:59:59", 1, -470.0, 2002, 5.549, "ヴォルガーノ", 2, 0.0, 10, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", "2025/09/16 15:00:00", 137701, 10040);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2025/12/22 14:59:59", 6, -470.0, 2002, 2.64, "ヴォルガーノ", 3, 0.0, 10, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", "2025/09/16 15:00:00", 137701, 10041);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/03/23 11:59:59", 4, -470.0, 2002, 7.642, "ライラエル", 7, 0.0, 11, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", "2025/12/15 15:00:00", 132801, 10042);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/03/23 11:59:59", 1, -470.0, 2002, 0.0, "ライラエル", 1, 0.0, 11, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", "2025/12/15 15:00:00", 132802, 10043);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/03/23 11:59:59", 1, -470.0, 2002, 0.0, "クローチェ", 1, 0.0, 11, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", "2025/12/15 15:00:00", 134502, 10044);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/03/23 11:59:59", 1, -470.0, 2002, 3.72, "クローチェ", 2, 0.0, 11, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", "2025/12/15 15:00:00", 134501, 10045);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/06/22 11:59:59", 1, -470.0, 2002, 4.991, "ネフィ＝ネラ", 2, 0.0, 12, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", "2026/03/16 12:00:00", 138201, 10046);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/06/22 11:59:59", 4, -470.0, 2002, 3.877, "ネフィ＝ネラ", 1, 0.0, 12, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", "2026/03/16 12:00:00", 138201, 10047);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/06/22 11:59:59", 6, -470.0, 2002, 1.71, "アラクネ", 4, 0.0, 12, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", "2026/03/16 12:00:00", 136001, 10048);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/06/22 11:59:59", 2, -470.0, 2002, 5.32, "アラクネ", 5, 0.0, 12, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", "2026/03/16 12:00:00", 136001, 10049);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/09/22 11:59:59", 4, -470.0, 2002, 3.727, "アネモネ", 9, 0.0, 13, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", "2026/06/15 12:00:00", 135401, 10050);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/09/22 11:59:59", 9, -470.0, 2002, 7.213, "アネモネ", 7, 0.0, 13, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", "2026/06/15 12:00:00", 135401, 10051);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (1, "2026/09/22 11:59:59", 2, -470.0, 2002, 1.874, "クリア", 1, 0.0, 13, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", "2026/06/15 12:00:00", 135301, 10052);
INSERT INTO `v1_b17694c024cc797abaface41b984ce8979a18c1aa920d4f027865ca805989c3a` VALUES (2, "2026/09/22 11:59:59", 2, -470.0, 2002, 0.0, "クリア", 2, 0.0, 13, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", "2026/06/15 12:00:00", 135301, 10053);
